const minimalPdf = Buffer.from(
  '%PDF-1.4\n' +
    '1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n' +
    '2 0 obj<</Type/Pages/Count 1/Kids[3 0 R]>>endobj\n' +
    '3 0 obj<</Type/Page/MediaBox[0 0 612 792]/Parent 2 0 R>>endobj\n' +
    'xref\n0 4\n0000000000 65535 f \n0000000009 00000 n \n0000000052 00000 n \n0000000101 00000 n \n' +
    'trailer<</Size 4/Root 1 0 R>>\n' +
    'startxref\n178\n%%EOF\n',
  'utf8',
);

const filename = 'rmapi-smoke-test.pdf';
const binary = await this.helpers.prepareBinaryData(
  minimalPdf,
  filename,
  'application/pdf',
);

return [
  {
    json: {
      filename,
      folder: '/Inbox',
    },
    binary: {
      data: binary,
    },
  },
];

const FOLDER_RE = /^(\/[A-Za-z0-9._-]+)+$/;
const STAGING = '/home/node/.n8n-files';

const item = $input.first();
if (!item.binary?.data) {
  throw new Error('Missing binary.data');
}

const filenameRaw = String(item.json.filename ?? item.binary.data.fileName ?? 'document.pdf');
const filename = filenameRaw.split(/[/\\]/).pop() || 'document.pdf';

const folder = String(item.json.folder ?? '/Inbox').replace(/\/$/, '') || '/Inbox';
if (!FOLDER_RE.test(folder)) {
  throw new Error(`Invalid folder "${folder}". Expected /Inbox or /Inbox/NZZ`);
}

const safeName =
  filename.replace(/[^A-Za-z0-9._-]+/g, '-').replace(/-+/g, '-').replace(/^[-.]+|[-.]+$/g, '') ||
  'document.pdf';
const base = `upload-${$execution.id}-${safeName}`;
const pdfName = base.endsWith('.pdf') ? base : `${base}.pdf`;

const outboxPdf = `${STAGING}/outbox/${pdfName}`;
const outboxMeta = `${outboxPdf}.meta.json`;
const donePdf = `${STAGING}/done/${pdfName}`;
const doneMeta = `${donePdf}.meta.json`;
const failedPdf = `${STAGING}/failed/${pdfName}`;
const failedMeta = `${failedPdf}.meta.json`;
const failedErr = `${STAGING}/failed/${pdfName}.err`;

const metaBinary = await this.helpers.prepareBinaryData(
  Buffer.from(JSON.stringify({ folder, name: filename }), 'utf8'),
  `${pdfName}.meta.json`,
  'application/json',
);

const pdfBinary = item.binary.data;
pdfBinary.fileName = pdfName;
pdfBinary.mimeType = pdfBinary.mimeType || 'application/pdf';

return [
  {
    json: {
      filename,
      folder,
      base: pdfName,
      outboxPdf,
      outboxMeta,
      donePdf,
      doneMeta,
      failedPdf,
      failedMeta,
      failedErr,
    },
    binary: {
      data: pdfBinary,
      meta: metaBinary,
    },
  },
];

const fs = require('fs');

const item = $input.first();
const { donePdf, doneMeta, failedPdf, failedMeta, failedErr, base, folder, filename } = item.json;
const timeoutMs = 60000;
const pollMs = 2000;

const start = Date.now();
while (Date.now() - start < timeoutMs) {
  if (fs.existsSync(donePdf)) {
    fs.rmSync(donePdf, { force: true });
    fs.rmSync(doneMeta, { force: true });
    return [{ json: { status: 'uploaded', filename, folder, base } }];
  }

  if (fs.existsSync(failedPdf) || fs.existsSync(failedErr)) {
    let err = 'rmapi upload failed';
    if (fs.existsSync(failedErr)) {
      err = fs.readFileSync(failedErr, 'utf8').trim() || err;
    }
    fs.rmSync(failedPdf, { force: true });
    fs.rmSync(failedMeta, { force: true });
    fs.rmSync(failedErr, { force: true });
    throw new Error(err);
  }

  await new Promise((resolve) => setTimeout(resolve, pollMs));
}

throw new Error(`Timed out waiting for rmapi upload (base=${base})`);
